import{_ as i,a0 as u,w as p,s as r,ao as d,I as a,x as e,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"每日Ubuntu小技巧  —— 让Windows访问你文件的最简单的方法 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧  —— 让Windows访问你文件的最简单的方法 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧  —— 让Windows访问你文件的最简单的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧  —— 让Windows访问你文件的最简单的方法 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips – Easiest Way To Access Your Files From Windows","title":"每日Ubuntu小技巧  —— 让Windows访问你文件的最简单的方法","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips – Easiest Way To Access Your Files From Windows.md","filePath":"[post].md"}'),l={name:"201310/Daily Ubuntu Tips – Easiest Way To Access Your Files From Windows.md"};function m(b,t,w,T,g,f){const s=u("Link");return p(),r("div",null,[t[11]||(t[11]=d(`<h1 id="每日ubuntu小技巧-——-让windows访问你文件的最简单的方法" tabindex="-1">每日Ubuntu小技巧 —— 让Windows访问你文件的最简单的方法 <a class="header-anchor" href="#每日ubuntu小技巧-——-让windows访问你文件的最简单的方法" aria-label="Permalink to “每日Ubuntu小技巧  —— 让Windows访问你文件的最简单的方法”">​</a></h1><p>不管你是一个新手还是精通Ubuntu和Windows的大牛，让Windows访问Ubuntu文件的最好的方式都是使用Samba。通过许多第三方工具可以很轻松的安装和管理。</p><p>对于想要了解怎么从Windows快速访问Ubuntu文件的新用户或者新手来说，这篇短文将会告诉你该怎么做。我们的目标是要帮助新用户。我们尽量将这篇教程写得通俗易懂，以便让新手看懂而不会遇到太大的困难。</p><p>在这里我们不会太注重了解Samba是什么或者怎么将它配置加入域这类细节。我们要做的就是告诉你怎么在Ubuntu中安装和设置Samba，让Windows可以访问Ubuntu的文件。</p><p>如果你想要更多的了解Samba，我建议你Google一下，或者查询下Wikipedia。首先在Ubuntu下打开你的终端，然后运行如下命令安装Samba和其他相关的工具。</p><pre><code>sudo apt-get install samba cifs-utils
</code></pre><p>上面这条命令将会安装Samba和其他相关的工具。在旧版的Ubuntu中，你可能需要使用<strong>smbfs</strong>替代cifs-utils。如果上面命令能够使用就更好了。</p><p>然后，使用gedit（或者其他工具）打开Samba主配置文件，然后进行如下更改。可以使用如下命令打开主配置文件：</p><pre><code>sudo gedit /etc/samba/smb.conf
</code></pre><p>文件打开后，查找如下行并取消其注释（删掉行首的“;”）。它应该是这样的：</p><pre><code>security = user
</code></pre><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/sambausersubuntu.png" alt=""></p><p>然后，向下滚动文件，找到下面这行，同时取消行首注释。</p><pre><code>[homes]
</code></pre><p>这将会允许用户访问访问home目录中的文件夹及文件。比如说，如果你 <strong>取消</strong> 注释了[homes]，用户可以通过键入服务器名加用户名的方式访问home目录。</p><pre><code>\\\\192.168.0.2\\username
</code></pre><p>然后，运行如下命令向Samba数据库添加你的账户信息。这样可以允许你使用Samba访问共享文件。</p><pre><code>sudo smbpasswd -a usernmame
</code></pre><p>用你自己的用户名替代上述的username。</p><p>当提示创建密码时，创建并确认即可。最后，重启Samba服务或者重启计算机。</p><p>通过Windows访问文件时，点击<strong>开始 –&gt; 运行</strong>然后输入如下内容。或者打开资源管理器输入如下内容，如图。</p><pre><code>\\\\ubuntu_machine_IP\\username
</code></pre><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/10/sambausersubuntu1.png" alt=""></p><p>Enjoy!</p><hr>`,25)),a("p",null,[t[1]||(t[1]=e("来自: ",-1)),n(s,{href:"http://www.liberiangeek.net/2013/10/daily-ubuntu-tips-easiest-way-access-files-windows/"},{default:o(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/10/daily-ubuntu-tips-easiest-way-access-files-windows/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("译者：",-1)),n(s,{href:"https://github.com/scusjs"},{default:o(()=>[...t[2]||(t[2]=[e("SCUSJS",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),n(s,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const U=i(l,[["render",m]]);export{_ as __pageData,U as default};
